package org.egov.dx.adapter.vendor.dto;

import com.fasterxml.jackson.annotation.JsonAlias;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

/**
 * Inbound DTO representing the response received from the third-party Aadhaar KYC gateway
 * after requesting an OTP dispatch.
 *
 * <p>Contains the HTTP response code, epoch timestamp, vendor transaction identifier, and payload details
 * including the generated {@code referenceId} which must be supplied when verifying the OTP.</p>
 *
 * @author UPYOG Team
 * @since 1.0.0
 */
@Getter
@Setter
@AllArgsConstructor
@NoArgsConstructor
@Builder
@ToString
public class VendorSendOtpResponse {

    /**
     * HTTP status code returned by the vendor gateway (e.g., 200 for success, 400 for bad request).
     */
    @JsonProperty("code")
    private Integer code;

    /**
     * Epoch timestamp (in milliseconds or seconds) generated by the vendor gateway.
     */
    @JsonProperty("timestamp")
    private Long timestamp;

    /**
     * Unique transaction identifier assigned by the vendor gateway.
     */
    @JsonProperty("transaction_id")
    @JsonAlias({"transactionId", "txnId"})
    private String transactionId;

    /**
     * Nested response data object containing OTP transaction metadata.
     */
    @JsonProperty("data")
    private VendorSendOtpResponseDetails data;

    /**
     * Nested payload holding transaction reference details.
     */
    @Getter
    @Setter
    @AllArgsConstructor
    @NoArgsConstructor
    @Builder
    @ToString
    public static class VendorSendOtpResponseDetails {

        /**
         * Unique reference ID generated for this OTP session.
         * This value is mandatory when calling the OTP verification endpoint.
         */
        @JsonProperty("reference_id")
        @JsonAlias("referenceId")
        private Long referenceId;

        /**
         * Entity type string returned by the provider gateway.
         * Example: "in.co.sandbox.kyc.aadhaar.okyc.otp.response"
         */
        @JsonProperty("@entity")
        @JsonAlias("entity")
        private String entity;

        /**
         * User-friendly message returned by the gateway (e.g. "OTP sent successfully").
         */
        @JsonProperty("message")
        private String message;
    }
}